local CoreBoxMaker = {}
local PRODUCTS = {
    iron_corebox = { name = "Železni jeklenka za jedrca", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni jeklenka za jedrca za livarje." },
    bronze_corebox = { name = "Bronast jeklenka za jedrca", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast jeklenka za jedrca za livarje." },
    silver_corebox = { name = "Srebrn jeklenka za jedrca", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn jeklenka za jedrca za livarje." },
    gilded_corebox = { name = "Pozlačen jeklenka za jedrca", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen jeklenka za jedrca za livarje." },
    jewel_set_corebox = { name = "Draguljast jeklenka za jedrca", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast jeklenka za jedrca za livarje." },
    royal_sovereign_corebox = { name = "Kraljevski suveren jeklenka za jedrca", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren jeklenka za jedrca z biseri za krono." },
}
local BUILDINGS = {
    corebox_workshop = { name = "Corebox delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    corebox_house = { name = "Corebox hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_corebox_atelier = { name = "Mojstrski corebox atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_corebox_palace = { name = "Suverena corebox palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
CoreBoxMaker.ironStock=18; CoreBoxMaker.bronzeStock=14; CoreBoxMaker.woodStock=12; CoreBoxMaker.leatherStock=8; CoreBoxMaker.silverStock=8; CoreBoxMaker.goldStock=6; CoreBoxMaker.jewelStock=4; CoreBoxMaker.pearlStock=4
CoreBoxMaker.productStock = {}; CoreBoxMaker.buildings = {}; CoreBoxMaker.maker = nil; CoreBoxMaker.activeMaking = {}; CoreBoxMaker.totalProducts = 0; CoreBoxMaker.dayTimer = 0
function CoreBoxMaker.init() CoreBoxMaker.ironStock=18; CoreBoxMaker.bronzeStock=14; CoreBoxMaker.woodStock=12; CoreBoxMaker.leatherStock=8; CoreBoxMaker.silverStock=8; CoreBoxMaker.goldStock=6; CoreBoxMaker.jewelStock=4; CoreBoxMaker.pearlStock=4; CoreBoxMaker.productStock={}; CoreBoxMaker.buildings={}; CoreBoxMaker.maker=nil; CoreBoxMaker.activeMaking={}; CoreBoxMaker.totalProducts=0; CoreBoxMaker.dayTimer=0; print("[CoreBoxMaker] Royal Core Box Maker System initialized (6 products, 4 buildings)") end
function CoreBoxMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CoreBoxMaker.maker={name=n or ("Jeklenkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Jeklenkar najet: %s (spretnost: %d)",CoreBoxMaker.maker.name,s),"success") end; return true end
function CoreBoxMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CoreBoxMaker.build(id) local ok,e=CoreBoxMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CoreBoxMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CoreBoxMaker.getQualityBonus() local b=0; for _,bd in ipairs(CoreBoxMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CoreBoxMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CoreBoxMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CoreBoxMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CoreBoxMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CoreBoxMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CoreBoxMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CoreBoxMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CoreBoxMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CoreBoxMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CoreBoxMaker.buildings==0 then return false,"Potrebna jeklenkarska delavnica" end; if not CoreBoxMaker.maker then return false,"Potreben jeklenkar" end; return true end
function CoreBoxMaker.make(pt,qty) qty=qty or 1; local ok,e=CoreBoxMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CoreBoxMaker.ironStock=CoreBoxMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CoreBoxMaker.bronzeStock=CoreBoxMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CoreBoxMaker.woodStock=CoreBoxMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CoreBoxMaker.leatherStock=CoreBoxMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CoreBoxMaker.silverStock=CoreBoxMaker.silverStock-d.silverCost*qty end; if d.goldCost then CoreBoxMaker.goldStock=CoreBoxMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CoreBoxMaker.jewelStock=CoreBoxMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CoreBoxMaker.pearlStock=CoreBoxMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CoreBoxMaker.maker then t=math.max(1,t-math.floor(CoreBoxMaker.maker.skill/13)) end; table.insert(CoreBoxMaker.activeMaking,{id="corebox_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CoreBoxMaker.completeMaking(m) local q=1.0+(CoreBoxMaker.getQualityBonus()/100); if CoreBoxMaker.maker then q=q+(CoreBoxMaker.maker.skill/140) end; q=math.min(2.5,q); CoreBoxMaker.productStock[m.productType]=(CoreBoxMaker.productStock[m.productType] or 0)+m.quantity; CoreBoxMaker.totalProducts=CoreBoxMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CoreBoxMaker.maker then CoreBoxMaker.maker.itemsMade=CoreBoxMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CoreBoxMaker.maker.skill=math.min(100,CoreBoxMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Jeklenka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"corebox.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CoreBoxMaker.update(dt) if not _G.state then return end; CoreBoxMaker.dayTimer=CoreBoxMaker.dayTimer+dt; if CoreBoxMaker.dayTimer>=30 then CoreBoxMaker.dayTimer=0; for i=#CoreBoxMaker.activeMaking,1,-1 do local m=CoreBoxMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CoreBoxMaker.completeMaking(m); table.remove(CoreBoxMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CoreBoxMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CoreBoxMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CoreBoxMaker.getStats() return {ironStock=CoreBoxMaker.ironStock,bronzeStock=CoreBoxMaker.bronzeStock,woodStock=CoreBoxMaker.woodStock,leatherStock=CoreBoxMaker.leatherStock,silverStock=CoreBoxMaker.silverStock,goldStock=CoreBoxMaker.goldStock,jewelStock=CoreBoxMaker.jewelStock,pearlStock=CoreBoxMaker.pearlStock,productStock=CoreBoxMaker.productStock,numBuildings=#CoreBoxMaker.buildings,hasMaker=CoreBoxMaker.maker~=nil,makerName=CoreBoxMaker.maker and CoreBoxMaker.maker.name or "—",makerSkill=CoreBoxMaker.maker and CoreBoxMaker.maker.skill or 0,activeMaking=#CoreBoxMaker.activeMaking,totalProducts=CoreBoxMaker.totalProducts} end
return CoreBoxMaker
